final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	s, n := readInt(), readInt()
	size := 1
	for size < s {
		size <<= 1
	}
	// key = count * 2^20 + index, so the minimum key is the least busy, lowest-numbered server
	const inf = 1 << 62
	t := make([]int, 2*size)
	for i := range t {
		t[i] = inf
	}
	for i := 0; i < s; i++ {
		t[size+i] = i
	}
	for i := size - 1; i > 0; i-- {
		t[i] = min(t[2*i], t[2*i+1])
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for k := 0; k < n; k++ {
		lo, hi := size, size+readInt()+1
		best := inf
		for lo < hi {
			if lo&1 == 1 {
				best = min(best, t[lo])
				lo++
			}
			if hi&1 == 1 {
				hi--
				best = min(best, t[hi])
			}
			lo >>= 1
			hi >>= 1
		}
		idx := best & (1<<20 - 1)
		p := size + idx
		t[p] += 1 << 20
		for p >>= 1; p > 0; p >>= 1 {
			t[p] = min(t[2*p], t[2*p+1])
		}
		if k > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(idx))
	}
	w.WriteByte('\n')
}

